```st
FUNCTION_BLOCK FB
VAR_INPUT
    enqueue   : BOOL;
    dequeue   : BOOL;
    reset     : BOOL;
    capacity  : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status       : WORD;
END_VAR
VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    headIdx      : DINT := 1;
    tailIdx      : DINT := 1;
    prevEnqueue  : BOOL := FALSE;
    prevDequeue  : BOOL := FALSE;
    firstCall    : BOOL := FALSE;
    count        : DINT := 0;
END_VAR

    // Initialise internal state on first call
    IF NOT firstCall THEN
        headIdx   := 1;
        tailIdx   := 1;
        count     := 0;
        firstCall := TRUE;
    END_IF

    // Default status: no error
    status := 16#0000;

    // Detect rising edges
    VAR enqueueRising : BOOL; END_VAR
    VAR dequeueRising : BOOL; END_VAR
    enqueueRising := enqueue AND NOT prevEnqueue;
    dequeueRising := dequeue AND NOT prevDequeue;

    // Reset has highest priority
    IF reset THEN
        count     := 0;
        headIdx   := 1;
        tailIdx   := 1;
        status    := 16#0000;
        prevEnqueue := enqueue;
        prevDequeue := dequeue;
        elementCount := count;
        RETURN;
    END_IF

    // Enqueue request
    IF enqueueRising THEN
        IF count < capacity THEN
            buffer[tailIdx] := item;
            tailIdx := (tailIdx MOD capacity) + 1;
            count := count + 1;
            status := 16#0000;
        ELSE
            status := 16#8002; // queue full
        END_IF
    END_IF

    // Dequeue request
    IF dequeueRising THEN
        IF count > 0 THEN
            item := buffer[headIdx];
            headIdx := (headIdx MOD capacity) + 1;
            count := count - 1;
            status := 16#0000;
        ELSE
            status := 16#8001; // queue empty
        END_IF
    END_IF

    // Update edge‑detection memory
    prevEnqueue := enqueue;
    prevDequeue := dequeue;

    // Expose current fill level
    elementCount := count;

END_FUNCTION_BLOCK
```

